{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C20"],
      "claim": "Pethidine, a 4-substituted piperidine opioid with the closest structural/functional analogy to the query's piperidine opioid scaffold, has absolute oral bioavailability 0.52 (0.47–0.61) in healthy subjects, clearly above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "Encainide, which shares an anilide, piperidine, and methoxy/methoxymethyl-like polar functionality with the query, has absolute oral bioavailability 32 ± 7% in normal subjects, supporting F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C44"],
      "claim": "Meptazinol, an opioid analgesic, has low absolute oral bioavailability (4.5–8.7%), but this is associated with phenolic conjugation and extensive first-pass metabolism; the query lacks the phenolic group, so this low-F evidence is less directly applicable.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is a fentanyl-like 4-anilidopiperidine. The closest high-transfer opioid evidence (pethidine) and anilide/piperidine evidence (encainide) show oral bioavailability above 20%, while the only low-F opioid (meptazinol) has a phenolic first-pass liability absent in the query. Therefore predict high.",
  "evidence_gaps": [
    "No direct fentanyl or fentanyl-analog oral bioavailability record is present.",
    "Meptazinol's low bioavailability mechanism is not fully transferable to the query.",
    "Encainide bioavailability is variable, though mean values remain above 20%."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

